// With noImplicitAny OFF (strict:false), `order` is implicitly any.
function total(order) {
  // typo: 'prices' should be 'price' — but order is any, so no error
  return order.items.reduce((sum, i) => sum + i.prices, 0);
}

const order = { items: [{ price: 10 }, { price: 5 }] };
console.log(total(order)); // NaN at runtime, no compile error

solution.code:
// With strict:true you must type the parameter; the typo becomes a compile error.
interface Order { items: { price: number }[]; }
function total(order: Order) {
  return order.items.reduce((sum, i) => sum + i.price, 0); // fixed
}

const order: Order = { items: [{ price: 10 }, { price: 5 }] };
console.log(total(order)); // 15

interface CompilerOptions {
  target?: string;
  module?: string;
  strict?: boolean;
  esModuleInterop?: boolean;
}

function normalize(user: CompilerOptions): CompilerOptions {
  const defaults: CompilerOptions = {
    target: 'ES2022',
    module: 'ESNext',
    strict: true,
    esModuleInterop: true
  };
  return { ...defaults, ...user }; // user values win
}

console.log(normalize({ strict: false }));
console.log(normalize({ target: 'ES2017' }));
